    async def create_schema(
        self,
        *,
        type_name: str,
        display_name: str,
        allowed_surfaces: typing.Sequence[SchemaRequestAllowedSurfacesItem],
        upsert: typing.Optional[bool] = None,
        description: typing.Optional[str] = OMIT,
        fields: typing.Optional[typing.Sequence[FieldDef]] = OMIT,
        lookup_fields: typing.Optional[typing.Sequence[LookupDef]] = OMIT,
        render_hints: typing.Optional[typing.Dict[str, RenderHintDef]] = OMIT,
        capabilities: typing.Optional[typing.Dict[str, bool]] = OMIT,
        index_mode: typing.Optional[SchemaRequestIndexMode] = OMIT,
        storage_profile: typing.Optional[SchemaRequestStorageProfile] = OMIT,
        active: typing.Optional[bool] = OMIT,
        user_id: typing.Optional[str] = OMIT,
        scopes: typing.Optional[typing.Sequence[str]] = OMIT,
        based_on: typing.Optional[str] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> SchemaResponse:
        """
        Defines a new record type with optional field definitions, validation rules, and lookup indexes. Idempotent by `typeName` within the same ownership scope: re-creating an existing `typeName` returns the existing schema rather than failing. The response's `created` field (and the HTTP status — 201 when created, 200 when an existing schema was returned) tells the two apart. To reconcile an existing schema to the submitted shape instead of returning it unchanged, set `?upsert=true` (this also requires the `schemas:u` scope; only legal schema changes are applied — migration-locked changes are rejected). Requires the `schemas:c` scope to create. Being returned the existing schema on a collision is a read of that schema's data and additionally requires the `schemas:r` scope — a credential holding `schemas:c` alone receives a `400` ("already in use") on collision instead of the schema.

        Parameters
        ----------
        type_name : str
            Unique type identifier for this schema. Immutable after creation.

        display_name : str
            Human-readable display name for this type, shown in UIs.

        allowed_surfaces : typing.Sequence[SchemaRequestAllowedSurfacesItem]
            Which typed surfaces may bind this schema by its id: `record`, `document`, `user`, or `entity`. Required and must be non-empty. Identity entities in ANY namespace — `org`, `client`, or one you registered, such as `team` — bind under the single `entity` surface; use the schema's `typeName` to distinguish them, not the surface. A schema may list several surfaces (for a shared type usable on both records and documents). This drives surface-scoped schema listing (`GET /v1/schemas?surface=`) and is enforced at bind time — for example, a document cannot bind a record-only schema.

        upsert : typing.Optional[bool]
            When `true`, if a schema with the same `typeName` already exists it is reconciled to the submitted shape (additive fields, lookups, renderHints, and `active` are applied) instead of being returned unchanged; `typeName` and migration-locked lookup attributes (`rangeEnabled`/`sortBy`/`sensitive`) cannot be changed and a request to do so is rejected. A re-applied upsert whose declared shape is unchanged is a no-op (no schema-version bump). Defaults to `false`. Requires the `schemas:u` scope.

        description : typing.Optional[str]
            Optional description of what this schema is for.

        fields : typing.Optional[typing.Sequence[FieldDef]]
            Field definitions used to validate record payloads. Omit for a bare schema that performs no payload validation.

        lookup_fields : typing.Optional[typing.Sequence[LookupDef]]
            Payload fields to index for direct lookup queries. Maximum 10 lookup fields.

        render_hints : typing.Optional[typing.Dict[str, RenderHintDef]]
            UI rendering hints keyed by field id.

        capabilities : typing.Optional[typing.Dict[str, bool]]
            Feature flags for this schema. `auditHistory` (default true) controls whether a change-history (version) trail is kept for this type's data; setting it false stops recording the trail but never affects your record or document data itself. `readAccessLog` (default false; opt-in) controls accounting-of-disclosures logging: when true, each governed read of this schema's records writes a retained, subject-enumerable access record. The effective value resolves in order: this schema flag, then your context's default, then the platform default (false).

        index_mode : typing.Optional[SchemaRequestIndexMode]
            Default search-index mode for instances of this type — applies to records of this type and to documents bound to this schema, unless the individual record or document sets its own indexMode. HYBRID, SEMANTIC, and TEXT make content searchable; NONE is store-only (the data is persisted, retrievable, and usable for lookups, but not searchable). Omit for no default: a record with no indexMode of its own then defaults to NONE, and a document with no indexMode is rejected.

        storage_profile : typing.Optional[SchemaRequestStorageProfile]
            Where this type's payload is stored. STANDARD (default): payloads of 4 KB or larger are externalized to S3, smaller ones are stored inline. LOW_LATENCY: always store inline for the lowest read latency. LARGE_PAYLOAD: always externalize to S3, which lifts the 400 KB item-size ceiling. For externalized types, list and lookup responses return only the indexed projection unless you pass `includePayload=true`.

        active : typing.Optional[bool]
            Whether this schema is active. An inactive schema rejects creation of new records of its type.

        user_id : typing.Optional[str]
            Owning user — the Vectros-assigned UUID of a user in your account. Optional; omit to create an account-wide shared schema. With an API key, this sets the schema's owner explicitly. With a scoped token, the user must match the token's identity claim (if set) or fall within the token's data scope.

        scopes : typing.Optional[typing.Sequence[str]]
            The schema's scope ownership, as `namespace:value` entries (at most 2 namespaces) — for example `["org:6ba7b810-9dad-11d1-80b4-00c04fd430c8", "group:eng-team"]`. `org` and `client` are built-in namespaces; others are custom scopes you define (lowercase, 2-32 chars). Resolve a namespace's UUID from your own identifier with `GET /v1/entities/{namespace}?externalId=`. Optional — omit for an account-wide shared schema. When supplied, this is the schema's COMPLETE scope declaration: for a token that stamps identity, entries must match the token's identity values. On update, omit to leave ownership unchanged, or supply the complete new selection (`[]` clears it). Filter lists by these values with `?scope=`.

        based_on : typing.Optional[str]
            The id of an existing schema this one is a CUSTOMIZATION of, when a schema named `typeName` already exists in this context — required in that case (a same-named schema without it is rejected: "specify basedOn"), and must be omitted when this create is the FIRST schema under that name (it becomes that name's shared base, and must be created with no `userId`/`scopes` — a root/unscoped credential). Must point directly at the base (one hop); a variant of a variant is not yet supported. Immutable once set. Every same-named schema in a context is provably related through this chain — see the recordType-shadowing design doc.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        SchemaResponse
            A schema with the same `typeName` already existed and was returned (`created: false`) — unchanged for an idempotent create, or reconciled when `?upsert=true`. The plain (non-upsert) case additionally requires the `schemas:r` scope.

        Examples
        --------
        import asyncio

        from vectros import AsyncVectrosApi, FieldDef, LookupDef

        client = AsyncVectrosApi(
            token="YOUR_TOKEN",
            base_url="https://yourhost.com/path/to/api",
        )


        async def main() -> None:
            await client.schemas.create_schema(
                type_name="intake_form",
                display_name="Client Intake Form",
                description="Captures initial client information",
                fields=[
                    FieldDef(
                        field_id="first_name",
                        field_type="string",
                        required=True,
                        searchable=True,
                    ),
                    FieldDef(
                        field_id="email",
                        field_type="string",
                        required=True,
                    ),
                ],
                lookup_fields=[
                    LookupDef(
                        field_name="email",
                        unique=True,
                    )
                ],
                capabilities={"auditHistory": True},
                allowed_surfaces=["record"],
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.create_schema(
            type_name=type_name,
            display_name=display_name,
            allowed_surfaces=allowed_surfaces,
            upsert=upsert,
            description=description,
            fields=fields,
            lookup_fields=lookup_fields,
            render_hints=render_hints,
            capabilities=capabilities,
            index_mode=index_mode,
            storage_profile=storage_profile,
            active=active,
            user_id=user_id,
            scopes=scopes,
            based_on=based_on,
            request_options=request_options,
        )
        return _response.data

    async def get_schema(self, id: str, *, request_options: typing.Optional[RequestOptions] = None) -> SchemaResponse:
        """
        Retrieves a single record schema by its id. Requires the `schemas:r` scope.

        Parameters
        ----------
        id : str
            The id of the schema to retrieve.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        SchemaResponse
            The requested schema.

        Examples
        --------
        import asyncio

        from vectros import AsyncVectrosApi

        client = AsyncVectrosApi(
            token="YOUR_TOKEN",
            base_url="https://yourhost.com/path/to/api",
        )


        async def main() -> None:
            await client.schemas.get_schema(
                id="6ba7b810-9dad-11d1-80b4-00c04fd430c8",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.get_schema(id, request_options=request_options)
        return _response.data

