    async def delete_schema(self, id: str, *, request_options: typing.Optional[RequestOptions] = None) -> None:
        """
        Permanently deletes a record schema. The request is refused with 409 if records of this type still exist — delete those records first, since every record must reference a live schema. A lineage base (a schema other schemas declare `basedOn`) also cannot be deleted while any such variant still exists — delete the variant schema(s) first. Requires the `schemas:d` scope.

        Parameters
        ----------
        id : str
            The id of the schema to delete.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        None

        Examples
        --------
        import asyncio

        from vectros import AsyncVectrosApi

        client = AsyncVectrosApi(
            token="YOUR_TOKEN",
            base_url="https://yourhost.com/path/to/api",
        )


        async def main() -> None:
            await client.schemas.delete_schema(
                id="6ba7b810-9dad-11d1-80b4-00c04fd430c8",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.delete_schema(id, request_options=request_options)
        return _response.data

    async def get_schema_versions(
        self,
        id: str,
        *,
        start_from: typing.Optional[str] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> ModelDataVersionPage:
        """
        Returns the audit trail of changes to a record schema, newest first (create, update, and delete). Schema version history is always recorded — there is no per-schema toggle to disable it. Requires the `schemas:r` scope.

        Parameters
        ----------
        id : str
            The id of the schema whose version history you want.

        start_from : typing.Optional[str]
            Pagination cursor — pass the `nextCursor` value from the previous page to fetch the next one.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        ModelDataVersionPage
            A paginated version history, as a `{data, nextCursor}` envelope.

        Examples
        --------
        import asyncio

        from vectros import AsyncVectrosApi

        client = AsyncVectrosApi(
            token="YOUR_TOKEN",
            base_url="https://yourhost.com/path/to/api",
        )


        async def main() -> None:
            await client.schemas.get_schema_versions(
                id="6ba7b810-9dad-11d1-80b4-00c04fd430c8",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.get_schema_versions(
            id, start_from=start_from, request_options=request_options
        )
        return _response.data
